input.content:
{{- if .Values.httpRoute.enabled -}}
{{- $fullName := include "elasticsearch.fullname" . -}}
apiVersion: gateway.networking.k8s.io/v1
kind: HTTPRoute
metadata:
  name: {{ $fullName }}-es-httproute
  labels:
    {{- include "elasticsearch.labels" . | nindent 4 }}
    {{- with .Values.httpRoute.labels }}
    {{- toYaml . | nindent 4 }}
    {{- end }}
  {{- with .Values.httpRoute.annotations }}
  annotations:
    {{- toYaml . | nindent 4 }}
  {{- end }}
spec:
  parentRefs:
    {{- toYaml .Values.httpRoute.parentRefs | nindent 4 }}
  rules:
  {{- range .Values.httpRoute.hosts }}
    - matches:
        - headers:
            - name: ":authority"
              value: {{ .hostname | quote }}
      backendRefs:
        - name: {{ .service | default (printf "%s-es-http" $fullName) }}
          port: {{ .port | default 9200 }}
          weight: 1
  {{- end }}
{{- end }}

